private static void solve() {
    int n = sc.nextInt(), d = sc.nextInt();
    int[] A = new int[n];
    for (int i = 0; i < n; i++) {
        A[i] = sc.nextInt();
    }
    int[] dp = new int[n];
    Arrays.fill(dp, 1);
    int max = 1;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < i; j++) {
            if (Math.abs(A[i] - A[j]) <= d) {
                dp[i] = Math.max(dp[i], dp[j] + 1);
            }
        }
        max = Math.max(max, dp[i]);
    }
    out.println(max);
}
